"""OpenAI Batch API helper module for LangExtract.

This module provides batch inference support using the OpenAI Batch API.
It handles:

- File-based batch submission (upload JSONL, create batch job).
- Job polling with timeout enforcement and cancellation.
- Result extraction and reordering to match the input prompt order.
- Optional job splitting into multiple sub-batches.

The OpenAI Batch API is asynchronous: prompts are serialized into a JSONL
file, uploaded via ``client.files.create``, and submitted with
``client.batches.create``. Each request line carries a ``custom_id`` in the
``idx-{n:06d}`` format so that results (which may be returned out of order)
can be re-associated with their original prompt.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
import dataclasses
import io
import json
import time
from typing import Any, Callable

from absl import logging

from langextract.core import exceptions

_KEY_IDX = "idx-"
_ENDPOINT = "/v1/chat/completions"
_BATCH_PURPOSE = "batch"

# Batch statuses that indicate the job has finished successfully.
_STATUS_COMPLETED = "completed"
# Batch statuses that indicate the job has terminally failed.
_TERMINAL_FAIL = frozenset({"failed", "expired", "cancelled"})

# Default timeout is intentionally larger than the 24h completion window so a
# job that runs for the full window is not prematurely cancelled.
_DEFAULT_TIMEOUT = 24 * 60 * 60 * 2  # 172800 seconds (48 hours).


@dataclasses.dataclass
class BatchConfig:
  """Configuration for OpenAI Batch API processing.

  Attributes:
    enabled: Whether batch mode is active.
    threshold: Minimum number of prompts required to trigger batch mode.
    completion_window: Batch completion window. Only '24h' is supported.
    poll_interval: Seconds to wait between job status checks.
    timeout: Maximum seconds to wait for a job before cancelling it. Defaults
      to more than 24 hours so a full-window job is not cancelled early.
    max_requests_per_job: Maximum number of requests submitted in a single
      batch job before splitting into additional jobs.
    metadata: Optional metadata forwarded to the batch creation call.
    on_job_create: Optional callback invoked with each created job object.
  """

  enabled: bool = False
  threshold: int = 50
  completion_window: str = "24h"
  poll_interval: int | float = 30
  timeout: int | float = _DEFAULT_TIMEOUT
  max_requests_per_job: int = 50000
  metadata: dict | None = None
  on_job_create: Callable[[Any], None] | None = None

  def __post_init__(self) -> None:
    """Validate configuration values on construction."""
    if self.completion_window != "24h":
      raise ValueError(
          "Unsupported completion_window "
          f"{self.completion_window!r}; only '24h' is supported."
      )

  @classmethod
  def from_dict(cls, obj: Any) -> "BatchConfig":
    """Coerce ``obj`` into a BatchConfig.

    Args:
      obj: A BatchConfig (returned unchanged), a bool (mapped to
        ``BatchConfig(enabled=obj)``), None (disabled config), or a mapping of
        constructor keyword arguments.

    Returns:
      A BatchConfig instance.

    Raises:
      TypeError: If ``obj`` is not a BatchConfig, bool, None, or mapping.
    """
    if isinstance(obj, cls):
      return obj
    if isinstance(obj, bool):
      return cls(enabled=obj)
    if obj is None:
      return cls(enabled=False)
    if isinstance(obj, Mapping):
      valid = {f.name for f in dataclasses.fields(cls)}
      filtered = {k: v for k, v in obj.items() if k in valid}
      return cls(**filtered)
    raise TypeError("batch must be a mapping")


def _get(obj: Any, key: str, default: Any = None) -> Any:
  """Read ``key`` from a mapping or an object attribute."""
  if isinstance(obj, Mapping):
    return obj.get(key, default)
  return getattr(obj, key, default)


def _as_file_id(value: Any) -> str | None:
  """Return ``value`` if it is a usable file id, else None."""
  if isinstance(value, str) and value:
    return value
  return None


def _content_to_text(content: Any) -> str:
  """Decode the payload returned by ``client.files.content`` to text."""
  if content is None:
    return ""
  if isinstance(content, str):
    return content
  if isinstance(content, (bytes, bytearray)):
    return bytes(content).decode("utf-8")

  text = getattr(content, "text", None)
  if isinstance(text, str):
    return text

  read = getattr(content, "read", None)
  if callable(read):
    data = read()
    if isinstance(data, (bytes, bytearray)):
      return bytes(data).decode("utf-8")
    if isinstance(data, str):
      return data

  raw = getattr(content, "content", None)
  if isinstance(raw, (bytes, bytearray)):
    return bytes(raw).decode("utf-8")
  if isinstance(raw, str):
    return raw

  return ""


def _is_permission_error(exc: Exception) -> bool:
  """Return True if ``exc`` represents an HTTP 403 (permission) error."""
  status = getattr(exc, "status_code", None)
  if status == 403:
    return True
  code = getattr(exc, "code", None)
  if code in (403, "403"):
    return True
  return "403" in str(exc)


def _extract_job_errors(errors: Any) -> str | None:
  """Build an error string from a failed job's ``errors`` field."""
  if not errors:
    return None
  data = _get(errors, "data")
  if data is None and isinstance(errors, (list, tuple)):
    data = errors
  messages: list[str] = []
  if data:
    for item in data:
      message = _get(item, "message")
      messages.append(str(message) if message else str(item))
  if messages:
    return "; ".join(messages)
  return str(errors)


def _error_message_from_obj(obj: Any) -> str:
  """Extract a human-readable error message from an output/error line."""
  err = _get(obj, "error")
  if err:
    message = _get(err, "message")
    if message:
      return str(message)
    if isinstance(err, Mapping):
      return json.dumps(err)
    return str(err)

  response = _get(obj, "response") or {}
  body = _get(response, "body") or {}
  body_err = _get(body, "error")
  if body_err:
    message = _get(body_err, "message")
    if message:
      return str(message)
    return json.dumps(body_err) if isinstance(body_err, Mapping) else str(
        body_err
    )

  return json.dumps(obj) if isinstance(obj, Mapping) else str(obj)


